import socket

# Try common ports or find the service
ports = [8080, 5000, 3000, 8000, 9000, 54321, 5432, 54322]
for port in ports:
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            result = s.connect_ex(('localhost', port))
            if result == 0:
                print(f"Port {port}: open")
    except:
        pass

# Also try 127.0.0.1
print("\nTrying 127.0.0.1:")
for port in ports:
